package com.bank.statement;

import java.util.logging.*;

public class ReverseListDemo {
    private static final Logger log = Logger.getLogger(ReverseListDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        StatementOrderService svc = new StatementOrderService();

        TxnNode head = TxnNode.of("T1", "T2", "T3", "T4");
        TxnNode revIter = svc.reverseIterative(head);
        log.info(() -> "Iterative reversed: " + TxnNode.asString(revIter));

        TxnNode head2 = TxnNode.of("T1", "T2", "T3", "T4");
        TxnNode revRec = svc.reverseRecursive(head2);
        log.info(() -> "Recursive reversed: " + TxnNode.asString(revRec));
    }
}

