class StatementOrderService {
    private static final Logger log = Logger.getLogger(StatementOrderService.class.getName());

    // Iterative: prev/curr/next. O(n) time, O(1) space.
    TxnNode reverseIterative(TxnNode head) {
        TxnNode prev = null, curr = head;
        while (curr != null) {
            TxnNode next = curr.next; // save the rest before flipping
            curr.next = prev;         // flip link backward
            prev = curr;              // advance prev
            curr = next;              // advance curr
        }
        return prev;                  // new head
    }

    // Recursive: reverse the tail, then fix this node. O(n) time, O(n) stack.
    TxnNode reverseRecursive(TxnNode head) {
        if (head == null || head.next == null) return head;
        TxnNode newHead = reverseRecursive(head.next);
        head.next.next = head;        // successor points back to current
        head.next = null;             // terminate old forward link
        return newHead;
    }
}

