class TxnNode {
    final String id;
    TxnNode next;
    TxnNode(String id) { this.id = id; }
    static TxnNode of(String... ids) {
        TxnNode head = null, tail = null;
        for (String id : ids) {
            TxnNode n = new TxnNode(id);
            if (head == null) { head = tail = n; }
            else { tail.next = n; tail = n; }
        }
        return head;
    }
    static String asString(TxnNode head) {
        StringBuilder sb = new StringBuilder();
        for (TxnNode n = head; n != null; n = n.next) {
            sb.append(n.id);
            if (n.next != null) sb.append(" -> ");
        }
        return sb.toString();
    }
}

